package com.motionstudio.part3
import com.motionstudio.part2.*
import kotlin.math.*
object MatteEngine{enum class Type{ALPHA,LUMA,INVERTED_ALPHA};fun apply(src:FrameBuffer,matte:FrameBuffer,type:Type,feather:Float=0f,expansion:Int=0):FrameBuffer{require(src.width==matte.width&&src.height==matte.height);var m=when(type){Type.ALPHA->matte;Type.INVERTED_ALPHA->invert(matte);Type.LUMA->luma(matte)};if(expansion!=0)m=if(expansion>0)dilate(m,expansion) else erode(m,-expansion);if(feather>0)m=BlurEngine.gaussian(m,feather);val o=FrameBuffer(src.width,src.height);for(y in 0 until src.height)for(x in 0 until src.width){val c=src.get(x,y);o.set(x,y,Rgba(c.r,c.g,c.b,c.a*m.get(x,y).r))};return o};private fun luma(f:FrameBuffer):FrameBuffer{val o=FrameBuffer(f.width,f.height);for(y in 0 until f.height)for(x in 0 until f.width){val c=f.get(x,y);val q=.2126f*c.r+.7152f*c.g+.0722f*c.b;o.set(x,y,Rgba(q,q,q,1f))};return o};private fun invert(f:FrameBuffer)=f.mapPixels{Rgba(1f,1f,1f,it.a).let{Rgba(1-it.r,1-it.g,1-it.b,it.a)}};private fun dilate(f:FrameBuffer,r:Int)=morph(f,r,true);private fun erode(f:FrameBuffer,r:Int)=morph(f,r,false);private fun morph(f:FrameBuffer,r:Int,maxi:Boolean):FrameBuffer{val o=FrameBuffer(f.width,f.height);for(y in 0 until f.height)for(x in 0 until f.width){var q=if(maxi)0f else 1f;for(j in -r..r)for(i in -r..r){val v=f.get((x+i).coerceIn(0,f.width-1),(y+j).coerceIn(0,f.height-1)).r;q=if(maxi)max(q,v)else minOf(q,v)};o.set(x,y,Rgba(q,q,q,1f))};return o}}
